pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        address user = address(0x1234);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.addToBalance{value: depositAmount}();
        uint256 balanceBefore = c.getBalance(user);
        vm.prank(user);
        try c.withdrawBalance() {} catch {}
        uint256 balanceAfter = c.getBalance(user);
        assertTrue(balanceAfter == 0 && user.balance >= depositAmount);
    }
}
